python3 - <<'PY'
import json, requests, re, html, time
from urllib.parse import quote
from xml.etree import ElementTree as ET

base='reports/openclaw-browser-videos'
with open(f'{base}/candidates.json',encoding='utf-8') as f:
    vids=json.load(f)

sess=requests.Session()
sess.headers.update({'User-Agent':'Mozilla/5.0'})
results=[]

def fetch_watch_html(url):
    r=sess.get(url, timeout=25)
    r.raise_for_status()
    return r.text

def parse_json_blob(text, key):
    m=re.search(rf'{re.escape(key)}\s*=\s*(\{{.*?\}});', text)
    if m:
        try:
            return json.loads(m.group(1))
        except Exception:
            return None
    return None

def extract_caption_tracks(html_text):
    m=re.search(r'"captionTracks":(\[.*?\])', html_text)
    if not m:
        return []
    try:
        return json.loads(m.group(1))
    except Exception:
        return []

def xml_to_text(xml_text):
    try:
        root=ET.fromstring(xml_text)
        lines=[]
        for node in root.findall('.//text'):
            t=''.join(node.itertext())
            t=html.unescape(t).replace('\n',' ').strip()
            if t:
                lines.append(t)
        return '\n'.join(lines)
    except Exception:
        return ''

def extract_description(html_text):
    patterns=[
        r'"shortDescription":"(.*?)"',
        r'"description":\{"simpleText":"(.*?)"\}'
    ]
    for p in patterns:
        m=re.search(p, html_text)
        if m:
            txt=m.group(1).encode('utf-8').decode('unicode_escape')
            return txt.replace('\\n','\n')
    return ''

def extract_chapters(html_text):
    names=re.findall(r'"title":\{"simpleText":"([^"]+)"\},"timeRangeStartMillis"', html_text)
    seen=[]
    for n in names:
        if n not in seen:
            seen.append(n)
    return seen[:30]

for i,v in enumerate(vids,1):
    item=dict(v)
    item.update({'transcript':'','transcript_source':'','description':'','chapters':[],'status':'pending'})
    try:
        html_text=fetch_watch_html(v['url'])
        open(f"{base}/{v['videoId']}.watch.html",'w',encoding='utf-8').write(html_text)
        tracks=extract_caption_tracks(html_text)
        item['description']=extract_description(html_text)
        item['chapters']=extract_chapters(html_text)
        transcript=''
        source=''
        for tr in tracks:
            lang=tr.get('languageCode','')
            kind=tr.get('kind','')
            name=''.join(r.get('text','') for r in tr.get('name',{}).get('runs',[])) if isinstance(tr.get('name'),dict) else ''
            if lang.startswith('zh') or lang.startswith('en') or kind=='asr':
                baseUrl=tr.get('baseUrl')
                if baseUrl:
                    xml=sess.get(baseUrl+'&fmt=srv3', timeout=25).text
                    transcript=xml_to_text(xml)
                    if transcript:
                        source=f"captionTrack:{lang}:{name or kind}"
                        break
        if transcript:
            item['transcript']=transcript
            item['transcript_source']=source
            item['status']='transcript_ok'
            open(f"{base}/{v['videoId']}.transcript.txt",'w',encoding='utf-8').write(transcript)
        else:
            item['status']='metadata_only'
        time.sleep(1.2)
    except Exception as e:
        item['status']='error'
        item['error']=str(e)
    results.append(item)

open(f'{base}/video_data.json','w',encoding='utf-8').write(json.dumps(results,ensure_ascii=False,indent=2))
print(json.dumps([{k:x.get(k) for k in ('videoId','status','transcript_source','error')} for x in results], ensure_ascii=False, indent=2))
